//! Parent-only Driver128 identity check over owned generated bytes.
//! This produces no launch token and does not witness a contained broker or worker.
use crate::{
    analysis_plan::PreparedIntake,
    driver_capture_reports::{Binding, Projection},
    general_broker_private_attestation::Claim,
    general_driver128_pending::MAX_PUBLIC_PROJECTION,
    general_execution_commitment::Request,
    general_worker_public_preflight::preflight_driver128_public_report,
    report_bundle::digest,
};
use serde::Serialize;

pub struct OwnedBytes<'a> {
    pub request: &'a [u8],
    pub plan: &'a [u8],
    pub target: &'a [u8],
    pub public_projection: &'a [u8],
    pub private_claim: &'a [u8],
    pub private_fixture: &'a [u8],
}

#[derive(Debug, Serialize)]
pub struct Receipt {
    pub schema: u32,
    pub profile: &'static str,
    pub request_sha256: String,
    pub resolved_plan_sha256: String,
    pub target_sha256: String,
    pub target_bytes: u64,
    pub private_claim_sha256: String,
    pub private_fixture_sha256: String,
    pub public_projection_sha256: String,
    pub report_identity_sha256: String,
    pub owned_resolved_plan_verified: bool,
    pub request_private_report_identity_verified: bool,
    pub source_tree_witness_verified: bool,
    pub containment_witness_verified: bool,
    pub broker_journal_verified: bool,
    pub general_worker_admitted: bool,
    pub guest_admission: bool,
    pub engine_applied: bool,
    pub guest_executed: bool,
}

/// Exact first journal record bound to a previously checked owned receipt.
/// This does not attest the filesystem, broker process, or later RPC events.
#[derive(Debug, Serialize)]
pub struct JournalStartWitness {
    pub schema: u32,
    pub profile: &'static str,
    pub owned_report_identity_sha256: String,
    pub request_sha256: String,
    pub private_claim_sha256: String,
    pub journal_start_sha256: String,
    pub journal_start_verified: bool,
    pub full_broker_journal_verified: bool,
    pub contained_broker_witness: bool,
    pub general_worker_admitted: bool,
    pub guest_admission: bool,
    pub engine_applied: bool,
    pub guest_executed: bool,
}

/// Use only after `inspect` has produced `owned` from independently read
/// staged bytes. Exact equality rejects a journal prefix with trailing data.
pub fn verify_private_journal_start(
    owned: &Receipt,
    raw_claim: &[u8],
    raw_journal: &[u8],
) -> Result<JournalStartWitness, &'static str> {
    if owned.schema != 1
        || owned.profile != "general_driver128_owned_preflight_v1"
        || !owned.owned_resolved_plan_verified
        || !owned.request_private_report_identity_verified
        || owned.broker_journal_verified
        || owned.general_worker_admitted
        || owned.guest_admission
        || owned.engine_applied
        || owned.guest_executed
        || digest(raw_claim) != owned.private_claim_sha256
    {
        return Err("Driver128 owned receipt or claim differs for journal start");
    }
    let claim = Claim::parse(raw_claim)?;
    if claim.request_sha256 != owned.request_sha256
        || claim.resolved_plan_sha256 != owned.resolved_plan_sha256
        || claim.fixture.original_sha256 != owned.private_fixture_sha256
    {
        return Err("Driver128 journal claim differs from owned identity");
    }
    let expected = claim.expected_journal_start(raw_claim)?;
    if raw_journal != expected {
        return Err("Driver128 private journal start differs from owned claim");
    }
    Ok(JournalStartWitness {
        schema: 1,
        profile: "general_driver128_journal_start_witness_v1",
        owned_report_identity_sha256: owned.report_identity_sha256.clone(),
        request_sha256: owned.request_sha256.clone(),
        private_claim_sha256: owned.private_claim_sha256.clone(),
        journal_start_sha256: digest(raw_journal),
        journal_start_verified: true,
        full_broker_journal_verified: false,
        contained_broker_witness: false,
        general_worker_admitted: false,
        guest_admission: false,
        engine_applied: false,
        guest_executed: false,
    })
}

/// Re-resolve actual parent-owned bytes, then bind the request, public target,
/// private fixture and structural report identity. `source_tree_sha256` and
/// `containment_sha256` are caller-supplied identity fields, not witnesses.
pub fn inspect(
    bytes: &OwnedBytes<'_>,
    source_tree_sha256: &str,
    containment_sha256: &str,
) -> Result<Receipt, &'static str> {
    if bytes.public_projection.len() > MAX_PUBLIC_PROJECTION {
        return Err("Driver128 public projection exceeds bound");
    }
    let intake = PreparedIntake::prepare_driver128(
        bytes.plan.to_vec(),
        vec![bytes.target.to_vec(), bytes.private_fixture.to_vec()],
    )
    .map_err(|_| "Driver128 owned intake could not resolve")?;
    if intake.resolved().executable()
        || intake.resolved().value()["guest_admission"] != false
        || intake.resolved().value()["engine_applied"] != false
        || intake.resolved().value()["budget"]["general_worker_admitted"] != false
    {
        return Err("Driver128 resolved plan claimed guest admission");
    }
    let request = Request::parse(bytes.request)?;
    request.verify(&intake)?;
    let request_sha256 = digest(bytes.request);
    let public = preflight_driver128_public_report(
        bytes.request,
        &request_sha256,
        bytes.plan,
        &[Some(bytes.target), None],
    )?;
    if public.guest_admission || public.complete_report_binding {
        return Err("Driver128 public preflight claimed execution or report completion");
    }
    let expected_projection =
        Projection::from_bytes(bytes.target).map_err(|_| "Driver128 target projection invalid")?;
    let observed_projection: Projection = serde_json::from_slice(bytes.public_projection)
        .map_err(|_| "Driver128 public projection schema invalid")?;
    if observed_projection != expected_projection
        || observed_projection.sha256() != public.target_input_sha256
        || observed_projection.size() != public.target_input_bytes
    {
        return Err("Driver128 public projection differs from owned target");
    }
    let claim = Claim::parse(bytes.private_claim)?;
    claim.verify_against_request(bytes.request, &intake)?;
    let private = claim.inspect(bytes.private_claim, bytes.private_fixture)?;
    if !private.private_bytes_inspected || private.guest_admission || private.guest_executed {
        return Err("Driver128 private fixture was not strictly inspected");
    }
    let binding = Binding::for_general_commitment(
        bytes.request,
        &intake,
        source_tree_sha256,
        containment_sha256,
    )
    .map_err(|_| "Driver128 structural report identity invalid")?;
    if binding.request_sha256 != request_sha256
        || binding.input_sha256 != public.target_input_sha256
        || binding.input_bytes != public.target_input_bytes
        || binding.recipe != public.service_name
    {
        return Err("Driver128 report identity differs from owned bytes");
    }
    let encoded =
        serde_json::to_vec(&binding).map_err(|_| "Driver128 report identity encoding failed")?;
    Ok(Receipt {
        schema: 1,
        profile: "general_driver128_owned_preflight_v1",
        request_sha256,
        resolved_plan_sha256: intake.resolved().sha256().into(),
        target_sha256: digest(bytes.target),
        target_bytes: bytes.target.len() as u64,
        private_claim_sha256: digest(bytes.private_claim),
        private_fixture_sha256: digest(bytes.private_fixture),
        public_projection_sha256: digest(bytes.public_projection),
        report_identity_sha256: digest(&encoded),
        owned_resolved_plan_verified: true,
        request_private_report_identity_verified: true,
        source_tree_witness_verified: false,
        containment_witness_verified: false,
        broker_journal_verified: false,
        general_worker_admitted: false,
        guest_admission: false,
        engine_applied: false,
        guest_executed: false,
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{analysis_plan::Arch, plan_runtime::Case};
    use serde_json::{Value, json};

    struct Generated {
        request: Vec<u8>,
        plan: Vec<u8>,
        target: Vec<u8>,
        projection: Vec<u8>,
        claim: Vec<u8>,
        fixture: Vec<u8>,
    }
    impl Generated {
        fn view(&self) -> OwnedBytes<'_> {
            OwnedBytes {
                request: &self.request,
                plan: &self.plan,
                target: &self.target,
                public_projection: &self.projection,
                private_claim: &self.claim,
                private_fixture: &self.fixture,
            }
        }
    }
    fn generated() -> Generated {
        let mut kernel = Case::Kernel17.generated(Arch::X64).unwrap();
        let fixture = Case::NativeReplay.generated(Arch::X64).unwrap().fixtures;
        let mut value: Value = serde_json::from_slice(&kernel.plan).unwrap();
        value["target"]["service_name"] = json!("TestDrv");
        value["persona"]["value"]["windows_build"] = json!(22631);
        value["capture"]["profile"] = json!("large_driver128_v1");
        value["capture"]["sources"] = json!(["memory_snapshots", "structural_pe"]);
        value["capture"]["retained_bytes"] = json!(256u64 * 1024 * 1024);
        value["capture"]["memory_scan_bytes"] = json!(128u64 * 1024 * 1024);
        value["reports"]["profile"] = json!("large_driver_v1");
        value["limits"]["worker_memory_mb"] = json!(2048);
        value["inputs"].as_array_mut().unwrap().push(json!({
            "id":"offline","name":"offline.json","roles":["offline_fixtures"],
            "mount":{"kind":"not_mounted"},"size":fixture.len(),"sha256":digest(&fixture),
        }));
        value["network"] = json!({"kind":"offline_exact_replay","input":"offline"});
        let plan = serde_json::to_vec(&value).unwrap();
        let target = kernel.inputs.remove(0);
        let intake =
            PreparedIntake::prepare_driver128(plan.clone(), vec![target.clone(), fixture.clone()])
                .unwrap();
        let request = serde_json::to_vec(
            &Request::from_intake(&intake, "20261019T120000Z-12345678".into()).unwrap(),
        )
        .unwrap();
        let claim =
            serde_json::to_vec(&Claim::from_verified_request(&request, &intake).unwrap()).unwrap();
        let projection = serde_json::to_vec(&Projection::from_bytes(&target).unwrap()).unwrap();
        Generated {
            request,
            plan,
            target,
            projection,
            claim,
            fixture,
        }
    }
    fn check(sample: &Generated) -> Result<Receipt, &'static str> {
        inspect(&sample.view(), &"1".repeat(64), &"2".repeat(64))
    }
    #[test]
    fn generated_owned_identity_is_complete_but_guest_stays_closed() {
        let sample = generated();
        let receipt = check(&sample).unwrap();
        assert_eq!(receipt.target_sha256, digest(&sample.target));
        assert_eq!(receipt.private_fixture_sha256, digest(&sample.fixture));
        assert!(receipt.owned_resolved_plan_verified);
        assert!(receipt.request_private_report_identity_verified);
        assert!(!receipt.source_tree_witness_verified);
        assert!(!receipt.containment_witness_verified);
        assert!(!receipt.broker_journal_verified);
        assert!(!receipt.general_worker_admitted);
        assert!(!receipt.guest_admission && !receipt.engine_applied && !receipt.guest_executed);
    }
    #[test]
    fn independently_tampered_owned_components_fail() {
        for field in 0..6 {
            let mut sample = generated();
            let raw = match field {
                0 => &mut sample.request,
                1 => &mut sample.plan,
                2 => &mut sample.target,
                3 => &mut sample.projection,
                4 => &mut sample.claim,
                _ => &mut sample.fixture,
            };
            raw[0] ^= 1;
            assert!(check(&sample).is_err(), "field {field} accepted");
        }
    }
    #[test]
    fn coordinated_resolved_hash_and_admission_tampering_fail() {
        let mut sample = generated();
        let mut request: Value = serde_json::from_slice(&sample.request).unwrap();
        request["reports_sha256"] = json!("a".repeat(64));
        sample.request = serde_json::to_vec(&request).unwrap();
        assert!(check(&sample).is_err());
        let mut sample = generated();
        let mut request: Value = serde_json::from_slice(&sample.request).unwrap();
        request["execution_authorized"] = json!(true);
        sample.request = serde_json::to_vec(&request).unwrap();
        assert!(check(&sample).is_err());
        let mut sample = generated();
        let mut claim: Value = serde_json::from_slice(&sample.claim).unwrap();
        claim["resolved_plan_sha256"] = json!("a".repeat(64));
        sample.claim = serde_json::to_vec(&claim).unwrap();
        assert!(check(&sample).is_err());
    }

    #[test]
    fn oversized_projection_is_refused_before_deserialization() {
        let mut sample = generated();
        sample.projection = vec![b' '; MAX_PUBLIC_PROJECTION + 1];
        assert!(check(&sample).is_err());
    }

    #[test]
    fn generated_private_journal_start_is_exactly_bound_without_full_broker_claim() {
        let sample = generated();
        let owned = check(&sample).unwrap();
        let claim = Claim::parse(&sample.claim).unwrap();
        let start = claim.expected_journal_start(&sample.claim).unwrap();
        let witness = verify_private_journal_start(&owned, &sample.claim, &start).unwrap();
        assert!(witness.journal_start_verified);
        assert_eq!(witness.journal_start_sha256, digest(&start));
        assert_eq!(
            witness.owned_report_identity_sha256,
            owned.report_identity_sha256
        );
        assert!(!witness.full_broker_journal_verified);
        assert!(!witness.contained_broker_witness);
        assert!(!witness.general_worker_admitted);
        assert!(!witness.guest_admission && !witness.engine_applied && !witness.guest_executed);
        let mut changed = start.clone();
        changed[0] ^= 1;
        assert!(verify_private_journal_start(&owned, &sample.claim, &changed).is_err());
        let mut trailing = start.clone();
        trailing.push(b'\n');
        assert!(verify_private_journal_start(&owned, &sample.claim, &trailing).is_err());
        let mut changed_claim = sample.claim.clone();
        changed_claim[0] ^= 1;
        assert!(verify_private_journal_start(&owned, &changed_claim, &start).is_err());
        let mut changed_owned = check(&sample).unwrap();
        changed_owned.request_sha256 = "0".repeat(64);
        assert!(verify_private_journal_start(&changed_owned, &sample.claim, &start).is_err());
        let mut changed_owned = check(&sample).unwrap();
        changed_owned.broker_journal_verified = true;
        assert!(verify_private_journal_start(&changed_owned, &sample.claim, &start).is_err());
    }
}
